import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int atCounter = 0;
        String strInput = scanner.nextLine();
        String tempStr = "";
        List<String> outputList = new ArrayList<>();

        if (!strInput.isEmpty()) {
            tempStr += strInput.charAt(0);
            outputList.add(tempStr);
        }

        int i = 1;
        while (i < strInput.length()) {
            String threeChar = "";
            String twoChar = "";

            if (i + 2 < strInput.length()) {
                threeChar = strInput.substring(i, i + 3);
            }
            if (i + 1 < strInput.length()) {
                twoChar = strInput.substring(i, i + 2);
            }

            if (threeChar.equals("dot")) {
                for (int j = 0; j < outputList.size(); j++) {
                    outputList.set(j, outputList.get(j) + ".");
                }
                i += 3;
            } else if (twoChar.equals("at")) {
                atCounter++;
                for (int j = 0; j < atCounter - 1; j++) {
                    String s = outputList.get(j);
                    outputList.set(j, s + "at");
                }
                for (int j = atCounter - 1; j < outputList.size(); j++) {
                    String s = outputList.get(j);
                    outputList.set(j, s + "@");
                }
                if (i + 1 < strInput.length()) {
                    tempStr += strInput.charAt(i);
                    tempStr += strInput.charAt(i + 1);
                }
                outputList.add(tempStr);
                i += 2;
            } else {
                char currentChar = strInput.charAt(i);
                tempStr += currentChar;
                for (int j = 0; j < outputList.size(); j++) {
                    outputList.set(j, outputList.get(j) + currentChar);
                }
                i++;
            }
        }

        if (!strInput.isEmpty()) {
            char lastChar = strInput.charAt(strInput.length() - 1);
            for (int j = 0; j < outputList.size(); j++) {
                outputList.set(j, outputList.get(j) + lastChar);
            }
        }

        Collections.sort(outputList);
        System.out.println(outputList.get(0));
        scanner.close();
    }
}
